 p=argparse.ArgumentParser(); p.add_argument('--run-id',required=True); p.add_argument('--rows',required=True); p.add_argument('--checkpoint-manifest',required=True); p.add_argument('--state-alignment',required=True); p.add_argument('--run-log',required=True); p.add_argument('--environment',required=True); p.add_argument('--sample-manifest',required=True); p.add_argument('--expected-probes',type=int,default=4); p.add_argument('--expected-branches',default='1,2,4,8,16'); p.add_argument('--expected-reference-rows',type=int,default=20); p.add_argument('--expected-resume-rows',type=int,default=20); p.add_argument('--expected-logical-segments',type=int,default=60); p.add_argument('--loss-epsilon',type=float,default=1e-4); p.add_argument('--jobs',type=int,default=1); a=p.parse_args(); root=Path(__file__).resolve().parents[1]; out=root/'runs'/a.run_id/'measured'; rd=lambda f:[json.loads(x) for x in Path(f).read_text().splitlines() if x.strip()]
 rows=rd(a.rows); cps=rd(a.checkpoint_manifest); als=rd(a.state_alignment); logs=rd(a.run_log); env=json.loads(Path(a.environment).read_text()); refs={r['row_key']:r for r in rows if r.get('arm')=='reference'}; ress={r['row_key']:r for r in rows if r.get('arm')=='resume'}; cp={x['row_key']:x for x in cps}; al={x['row_key']:x for x in als}; pairs=[]; missing=[]
